from .exceptions import MessageQueryParserError
from .message_query_tokenizer import tokens, find_column  # Noqa: F401
from . import message_query as msg_query
from . import query_language_functions  # Noqa: F401

"""
Query language for asking message about its content


syntax EBNF:

query                           : composed_query
                                | simple_query
composed_query                  : braced_query
                                | negated_query
                                | and_or_query
braced_query                    : ( query )
negated_query                   : NOT query
and_or_query                    : query AND query
                                | query OR query
simple_query                    : comparator
                                | field_existence_checker
                                | substructure_checker
comparator                      : field_vs_field_comparator
                                | field_vs_function_comparator
field_vs_field_comparator       : comparision_operand COMPARE_OPERATOR comparision_operand
comparision_operand             : field_related_operand
                                | value_related_operand
field_existence_checker         : FIELD_SELECTOR EXISTENCE_OPERATOR
substructure_checker            : FIELD_SELECTOR CONTAINS query_list
                                | FIELD_SELECTOR CONTAINS simple_value_list
query_list                      : ( query_list_content )
simple_value_list               : ( simple_value_list_content )
query_list_content              : query
                                | query , query_list_content
simple_value_list_content       : simple_value
                                | simple_value, simple_value_list_content
field_related_operand           : field_selector
                                | function_on_field_call
field_selector                  : FIELD_SELECTOR
function_on_field_call          : FUNCTION_ON_FIELD_CALL
value_related_operand           : simple_value
                                | function_on_value_call
function_on_value_call          : FUNCTION_CALL
field_vs_function_comparator    : FIELD_SELECTOR FULFILLS FUNCTION_CALL             # FUNCTION_CALL.value['field_selector'] = FIELD_SELECTOR.value
simple_value                    : INTEGER_VALUE
                                | STRING_VALUE

"""  # pylint: disable=pointless-string-statement


def p_error(p):
    """
    Error

    :param p:
    """
    if p is None:
        raise MessageQueryParserError(None, 0, 0, None)
    whole_query = p.lexer.lexdata
    line = p.lineno
    column = find_column(p)
    token_value = p.value
    raise MessageQueryParserError(token_value, line, column, whole_query)
    # err = MessageQueryParserError(token_value, line, column, whole_query)
    # print err


def p_query(p):  # noqa: D403
    """
    query : simple_query
          | composed_query
    """
    p[0] = {'grammar': {'production': 'query', 'grammar_result': p[1]['grammar']['grammar_result']},
            'action_result': p[1]['action_result']}


def p_simple_query(p):
    """
    simple_query : comparator
                 | field_existence_checker
                | substructure_checker
    """
    p[0] = {'grammar': {'production': 'simple_query', 'grammar_result': p[1]['grammar']['grammar_result']},
            'action_result': p[1]['action_result']}


def p_composed_query(p):
    """
    composed_query : braced_query
                   | negated_query
                   | and_or_query
    """
    p[0] = {'grammar': {'production': 'composed_query', 'grammar_result': p[1]['grammar']['grammar_result']},
            'action_result': p[1]['action_result']}


def p_braced_query(p):
    """braced_query : '(' query ')'"""
    p[0] = {'grammar': {'production': 'braced_query',
                        'grammar_result': (p[1], p[2]['grammar']['grammar_result'], p[3])},
            'action_result': p[2]['action_result']}


def p_negated_query(p):
    """negated_query : NOT query"""
    query_to_negate = p[2]['action_result']
    func_returning_negation = msg_query.f_not(query_to_negate)
    p[0] = {'grammar': {'production': 'negated_query',
                        'grammar_result': (p[1], p[2]['grammar']['grammar_result'])},
            'action_result': func_returning_negation}


def p_and_or_query(p):
    """
    and_or_query : query AND query
                 | query OR query
    """
    left_operand_function = p[1]['action_result']
    logical_operator = p[2]
    right_operand_function = p[3]['action_result']
    fun_returning_logical_result = msg_query.f_or_and(left_operand_function, logical_operator, right_operand_function)
    p[0] = {'grammar': {'production': 'and_or_query',
                        'grammar_result': (p[1]['grammar']['grammar_result'], p[2], p[3]['grammar']['grammar_result'])},
            'action_result': fun_returning_logical_result}


def p_comparator(p):  # noqa: D403
    """
    comparator : field_vs_field_comparator
               | field_vs_function_comparator
    """
    p[0] = {'grammar': {'production': 'comparator', 'grammar_result': p[1]['grammar']['grammar_result']},
            'action_result': p[1]['action_result']}


def p_field_vs_function_comparator(p):
    """field_vs_function_comparator : FIELD_SELECTOR FULFILLS FUNCTION_CALL"""
    field_selector = p[1]
    fun_returning_value = msg_query.get_field_value_access_function(field_selector)
    registered_wrapped_function = p[3]['function']
    registered_function_second_parameter = p[3]['parameter_string']
    func_to_call = msg_query.get_fulfills_comparator(fun_returning_value, registered_wrapped_function, registered_function_second_parameter)
    p[0] = {'grammar': {'production': 'function_on_field_call', 'grammar_result': (p[1], p[2], p[3])}, 'action_result': func_to_call}


def p_field_vs_field_comparator(p):
    """field_vs_field_comparator : comparison_operand COMPARE_OPERATOR comparison_operand"""
    left_function_value_accessor = p[1]['action_result']
    operator = p[2]
    right_function_value_accessor = p[3]['action_result']
    fun_returning_comparison_result = msg_query.get_value_comparator_function(left_function_value_accessor, operator, right_function_value_accessor)
    p[0] = {'grammar': {'production': 'field_vs_field_comparator',
                        'grammar_result': (operator, p[1]['grammar']['grammar_result'], p[3]['grammar']['grammar_result'])},
            'action_result': fun_returning_comparison_result}


def p_field_existence_checker(p):
    """field_existence_checker : FIELD_SELECTOR EXISTENCE_OPERATOR"""
    field_selector = p[1]
    existence_operator = p[2]
    fun_returning_existence_result = msg_query.check_field_existence_function(field_selector, existence_operator)
    p[0] = {'grammar': {'production': 'field_existence_checker',
                        'grammar_result': (p[1], p[2])},
            'action_result': fun_returning_existence_result}


def p_comparison_operand(p):
    """
    comparison_operand : value_related_operand
                       | field_related_operand
    """
    p[0] = {'grammar': {'production': 'comparison_operand', 'grammar_result': p[1]['grammar']['grammar_result']},
            'action_result': p[1]['action_result']}


def p_field_related_operand(p):
    """
    field_related_operand : field_selector
                          | function_on_field_call
    """
    p[0] = {'grammar': {'production': 'field_related_operand', 'grammar_result': p[1]['grammar']['grammar_result']},
            'action_result': p[1]['action_result']}


def p_field_selector(p):
    """field_selector : FIELD_SELECTOR"""
    fun_returning_value = msg_query.get_field_value_access_function(p[1])
    p[0] = {'grammar': {'production': 'field_selector', 'grammar_result': p[1]}, 'action_result': fun_returning_value}


def p_function_on_field_call(p):
    """function_on_field_call : FUNCTION_ON_FIELD_CALL"""
    field_selector = p[1]['field_selector']
    fun_returning_value = msg_query.get_field_value_access_function(field_selector)
    registered_wrapped_function = p[1]['function']
    registered_function_second_parameter = p[1]['parameter_string']
    func_to_call = msg_query.get_function_on_field_function(fun_returning_value, registered_wrapped_function, registered_function_second_parameter)
    p[0] = {'grammar': {'production': 'function_on_field_call', 'grammar_result': p[1]}, 'action_result': func_to_call}


def p_value_related_operand(p):
    """
    value_related_operand : simple_value
                          | function_on_value_call
    """
    p[0] = {'grammar': {'production': 'value_related_operand', 'grammar_result': p[1]['grammar']['grammar_result']},
            'action_result': p[1]['action_result']}


def p_function_on_value_call(p):
    """function_on_value_call : FUNCTION_CALL"""
    registered_wrapped_function = p[1]['function']
    registered_function_parameter = p[1]['parameter_string']
    func_to_call = msg_query.get_function_on_value_function(registered_wrapped_function, registered_function_parameter)
    p[0] = {'grammar': {'production': 'function_on_value_call', 'grammar_result': p[1]}, 'action_result': func_to_call}


def p_simple_value(p):
    """
    simple_value : INTEGER_VALUE
                 | STRING_VALUE
    """
    fun_returning_value = msg_query.get_value_access_function(p[1])
    p[0] = {'grammar': {'production': 'simple_value', 'grammar_result': p[1]}, 'action_result': fun_returning_value}


def p_substructure_checker(p):
    """
    substructure_checker : FIELD_SELECTOR CONTAINS query_list
                         | FIELD_SELECTOR CONTAINS simple_value_list
    """
    field_selector = p[1]
    query_list = p[3]['action_result']
    fun_returning_value = msg_query.get_field_value_access_function(field_selector)

    contains_comparator = msg_query.get_contains_comparator_2(fun_returning_value, query_list)
    p[0] = {'grammar': {'production': 'substructure_checker', 'grammar_result': (p[1], p[2], p[3]['grammar']['grammar_result'])},
            'action_result': contains_comparator}


def p_query_list(p):
    """query_list : '(' query_list_content ')'"""
    p[0] = {'grammar': {'production': 'query_list', 'grammar_result': [p[2]['grammar']['grammar_result']]},
            'action_result': p[2]['action_result']}


def p_query_list_content(p):
    """
    query_list_content : query
                       | query "," query_list_content
    """
    if len(p) == 2:  # single parameter
        p[0] = {'grammar': {'production': 'query_list_content', 'grammar_result': [p[1]['grammar']['grammar_result']]},
                'action_result': [p[1]['action_result']]}
    else:
        left_grammar_result = p[1]['grammar']['grammar_result']
        right_grammar_result = p[3]['grammar']['grammar_result']
        result_grammar = right_grammar_result
        result_grammar.append(left_grammar_result)

        query = p[1]['action_result']
        query_list = p[3]['action_result']
        result_list = [query]
        result_list.extend(query_list)  # make copy and keep order: query_list after query

        p[0] = {'grammar': {'production': 'query_list_content', 'grammar_result': result_grammar},
                'action_result': result_list}


def p_simple_value_list(p):
    """simple_value_list : '(' simple_value_list_content ')'"""
    p[0] = {'grammar': {'production': 'simple_value_list', 'grammar_result': [p[2]['grammar']['grammar_result']]},
            'action_result': p[2]['action_result']}


def p_simple_value_list_content(p):
    """
    simple_value_list_content : simple_value
                              | simple_value "," simple_value_list_content
    """
    if len(p) == 2:  # single parameter
        p[0] = {'grammar': {'production': 'simple_value_list_content', 'grammar_result': [p[1]['grammar']['grammar_result']]},
                'action_result': [p[1]['action_result']]}
    else:
        left_grammar_result = p[1]['grammar']['grammar_result']
        right_grammar_result = p[3]['grammar']['grammar_result']
        result_grammar = right_grammar_result
        result_grammar.append(left_grammar_result)

        value = p[1]['action_result']
        value_list = p[3]['action_result']
        result_list = [value]
        result_list.extend(value_list)  # make copy and keep order: value_list after value

        p[0] = {'grammar': {'production': 'simple_value_list_content', 'grammar_result': result_grammar},
                'action_result': result_list}
